var listener = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback, 0);
try {
    listener.Start();
    var actual = (System.Net.IPEndPoint)listener.LocalEndpoint;
    Console.WriteLine(actual.Address); // 127.0.0.1
    Console.WriteLine(actual.Port > 0);
} finally { listener.Stop(); }
